import { visuallyHiddenStyle } from "../../a11y/visually-hidden";
import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import { isComposingEvent, isPrimaryPointer } from "../../dom/event";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction, type RovingAction } from "../../focus/roving-focus";
import { isTypeaheadKey } from "../../interaction/typeahead";
import type { HTMLProps, NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import type { Align, Side } from "../../positioner/compute-position";
import { parts } from "./select.anatomy";
import {
  getBackdropId,
  getCancelTriggerId,
  getContentEl,
  getContentId,
  getHiddenSelectId,
  getIndicatorId,
  getItemGroupId,
  getItemGroupLabelId,
  getItemId,
  getPositionerId,
  getTriggerId,
  getValueTextId,
} from "./select.dom";
import type {
  SelectApi,
  SelectItemGroupLabelProps,
  SelectItemGroupProps,
  SelectItemIndicatorProps,
  SelectItemProps,
  SelectSchema,
} from "./select.types";

/**
 * A mirror of `interaction/typeahead`'s DEFAULT_TIMEOUT, restated because the
 * buffer keeps that number private and the Space arbitration below needs it: a
 * Space *during* a live search is a search character (APG), and "during" is
 * exactly the window the buffer itself would still extend.
 */
const TYPEAHEAD_WINDOW_MS = 350;

/**
 * Which end of the list a key on the **trigger** opens onto. Unlike the menu's
 * table, Enter and the arrows answer `next`/`prev` rather than `first`/`last`:
 * `highlightInitial` gives the *selected* item priority over either end, and
 * only Home and End are allowed to force their way past it.
 */
function getTriggerOpenAction(key: string): RovingAction | null {
  switch (key) {
    case "Enter":
    case "ArrowDown":
      return "next";
    case "ArrowUp":
      return "prev";
    case "Home":
      return "first";
    case "End":
      return "last";
    default:
      return null;
  }
}

export function connect<T extends PropTypes>(
  service: Service<SelectSchema>,
  normalize: NormalizeProps<T>,
): SelectApi<T> {
  const { context, computed, prop, refs, send, scope } = service;

  const open = context.get("open");
  const disabled = prop("disabled");
  const invalid = prop("invalid");
  const required = prop("required");
  const presentation = computed("presentation");
  const dir = prop("dir");
  const state = open ? "open" : "closed";
  const placement = context.get("currentPlacement");
  const [side, align = "center"] = placement.split("-") as [Side, Align | undefined];

  const triggerId = getTriggerId(scope);
  const contentId = getContentId(scope);
  const value = context.get("value");
  const valueLabel = context.get("valueLabel");
  const hasValue = computed("hasValue");
  const highlightedValue = context.get("highlightedValue");
  const flashingValue = context.get("flashingValue");
  const hasSymbols = context.get("hasSymbolGutter");
  const focusSource = context.get("focusSource");

  /**
   * Whether a Space right now is a search character rather than a commit. Read
   * off the shared buffer at event time, never at render: the answer changes
   * with the clock, not with the props.
   */
  function isTypeaheadActive(): boolean {
    const buffer = refs.get("typeahead");
    return buffer.query !== "" && Date.now() - buffer.lastKeyAt <= TYPEAHEAD_WINDOW_MS;
  }

  /**
   * Every key the surface answers, on `content` alone: a keydown bubbles out of
   * the focused option to here, so one table serves the whole listbox.
   */
  function onContentKeyDown(event: KeyboardEvent): void {
    if (isComposingEvent(event)) return;

    const { key } = event;

    // The one combination that survives the modifier gate below, and the mirror
    // of the Alt+ArrowDown that opens the surface: APG select-only gives
    // Alt+ArrowUp the same outcome as Enter — commit the highlighted option,
    // close, hand the focus back to the trigger. It used to be swallowed whole,
    // because the gate ran first and answered every `altKey` with "not ours".
    if (key === "ArrowUp" && event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey) {
      event.preventDefault();
      send({ type: "ITEM.COMMIT" });
      return;
    }

    if (event.ctrlKey || event.metaKey || event.altKey) return;

    // APG select-only: Tab commits the highlighted option and closes, then
    // `proxyTabFocus` places the focus after the trigger. Answered ahead of the
    // `defaultPrevented` gate for the menu's exact reason — the proxy listens on
    // the document in capture and prevents the default on the roving item.
    //
    // It commits, which is what the APG asks for and the only coherent answer
    // here: moving the highlight does not move the value in this component, so a
    // Tab that dropped the highlight would silently discard the only thing the
    // keyboard user had done. The default is left alone — the focus still has to
    // leave.
    if (key === "Tab") {
      send({ type: "ITEM.COMMIT" });
      return;
    }

    if (event.defaultPrevented) return;

    // Escape belongs to the dismissable layer, which listens on the document in
    // capture and only answers for the top-most layer.
    if (key === "Escape") return;

    if (key === "Enter") {
      if (event.repeat) return;
      event.preventDefault();
      send({ type: "ITEM.ACTIVATE" });
      return;
    }

    // Space commits on keyup (the APG split) — unless a search is live, in
    // which case it is a character of that search and never a commit.
    if (key === " ") {
      event.preventDefault();
      if (prop("typeahead") && isTypeaheadActive()) send({ type: "TYPEAHEAD.KEY", key: " " });
      return;
    }

    // The optional half of the APG select-only table, and it is answered rather
    // than left to the browser. The claim it replaces — "the focus is real and
    // inside the scroller, so the browser pages the list itself" — is half true
    // and therefore wrong: the browser scrolls the scroller and leaves the
    // roving tabindex behind, so the highlight ends up off-screen and the next
    // arrow key snaps the view back to where the eye no longer is.
    if (key === "PageDown" || key === "PageUp") {
      event.preventDefault();
      send({ type: "HIGHLIGHT.PAGE", direction: key === "PageDown" ? "next" : "prev" });
      return;
    }

    // Resolved here rather than at the `dir` hoist in `connect`: with no `dir`
    // prop the answer is read off the surface, and a DOM read at the top of
    // `connect` would run on the server.
    const action = getRovingKeyAction(key, {
      orientation: "vertical",
      dir: resolveDir(dir, getContentEl(scope)),
    });
    if (action !== null) {
      event.preventDefault();
      send({ type: "HIGHLIGHT.MOVE", action });
      return;
    }

    if (prop("typeahead") && isTypeaheadKey(key)) {
      event.preventDefault();
      send({ type: "TYPEAHEAD.KEY", key });
    }
  }

  function onContentKeyUp(event: KeyboardEvent): void {
    if (event.defaultPrevented || event.key !== " ") return;
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    // The keydown half just fed this very Space to the buffer, so the window is
    // still open — which is exactly what marks the release as "not a commit".
    if (prop("typeahead") && isTypeaheadActive()) return;
    event.preventDefault();
    send({ type: "ITEM.ACTIVATE" });
  }

  function itemProps(item: SelectItemProps): HTMLProps {
    const itemDisabled = disabled || item.disabled === true;
    const highlighted = !itemDisabled && highlightedValue === item.value;
    const selected = value === item.value;

    return {
      id: getItemId(scope, item.value),
      role: "option",
      // Roving: exactly one stop in the tab order, and it is the highlighted
      // item. Never `aria-activedescendant` — the focus is real (règle dure).
      tabIndex: highlighted ? 0 : -1,
      // The selection, never the highlight: `aria-selected` is what the value
      // owns, and the moving focus already announces itself.
      "aria-selected": boolAttr(selected),
      "aria-disabled": ariaAttr(itemDisabled),
      "data-value": item.value,
      "data-label": item.label,
      "data-state": selected ? "checked" : "unchecked",
      "data-highlighted": dataAttr(highlighted),
      "data-disabled": dataAttr(itemDisabled),
      "data-highlighted-flash": dataAttr(flashingValue === item.value),
      "data-focus-source": highlighted ? (focusSource ?? undefined) : undefined,
      onPointerMove(event) {
        // A touch pointermove is a scroll or a long press, never a hover.
        if (event.pointerType === "touch" || itemDisabled) return;
        send({ type: "ITEM.POINTERMOVE", value: item.value });
      },
      onPointerLeave(event) {
        if (event.pointerType === "touch") return;
        send({ type: "ITEM.POINTERLEAVE", value: item.value });
      },
      onClick(event) {
        if (event.defaultPrevented || itemDisabled) return;
        send({ type: "ITEM.CLICK", value: item.value });
      },
    };
  }

  return {
    open,
    value,
    valueLabel,
    hasValue,
    highlightedValue,
    presentation,
    placement,
    triggerId,
    contentId,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },

    setValue(next: string | null): void {
      send({ type: "VALUE.SET", value: next });
    },

    clearValue(): void {
      send({ type: "VALUE.SET", value: null });
    },

    setHighlightedValue(next: string | null): void {
      send({ type: "HIGHLIGHT.SET", value: next });
    },

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        id: triggerId,
        type: "button",
        disabled,
        // The APG Combobox select-only pattern: the trigger *is* the combobox,
        // and its value is its contents — which is what `valueText` renders.
        role: "combobox",
        "aria-haspopup": "listbox",
        "aria-expanded": boolAttr(open),
        // Unconditional, unlike the menu's: the content is always mounted, so
        // the IDREF always resolves.
        "aria-controls": contentId,
        "aria-required": ariaAttr(required),
        "aria-invalid": ariaAttr(invalid),
        "aria-describedby": prop("describedBy"),
        "aria-labelledby": prop("labelledBy"),
        // `role="combobox"` takes no name from its contents — the contents are
        // the *value* — so a select composed outside a field would be nameless
        // (axe: `aria-input-field-name`). The `label` prop names the combobox
        // too, exactly as the spec reads; `labelledBy` outranks it by ARIA
        // precedence, and it is withheld under one only to keep one voice.
        "aria-label": prop("labelledBy") === undefined ? prop("label") : undefined,
        "data-state": state,
        "data-placeholder": dataAttr(!hasValue),
        "data-disabled": dataAttr(disabled),
        "data-invalid": dataAttr(invalid),
        "data-presentation": presentation,
        onPointerDown(event) {
          if (event.defaultPrevented || disabled || !isPrimaryPointer(event)) return;
          // Touch waits for the click: a surface that opened under a finger
          // would swallow the tap that was meant to reach the button.
          if (event.pointerType === "touch") return;
          send({ type: "TRIGGER.POINTERDOWN" });
        },
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || disabled || isComposingEvent(event)) return;
          if (event.ctrlKey || event.metaKey) return;
          // Alt is only ever part of the APG's Alt+Arrow openers.
          if (event.altKey && event.key !== "ArrowDown" && event.key !== "ArrowUp") return;

          // Space opens on keyup — the APG split, and what stops the press from
          // leaking into the surface it opens (see the menu trigger).
          if (event.key === " ") {
            event.preventDefault();
            return;
          }

          const action = getTriggerOpenAction(event.key);
          if (action !== null) {
            // The arrows must not scroll the page, and Enter on a real <button>
            // would otherwise synthesise a click read as a second press.
            event.preventDefault();
            send({ type: "TRIGGER.KEYDOWN", action });
            return;
          }

          // APG select-only: a printable character opens and highlights the
          // first match. The machine defers the key until the items exist.
          if (prop("typeahead") && isTypeaheadKey(event.key)) {
            event.preventDefault();
            send({ type: "TYPEAHEAD.KEY", key: event.key });
          }
        },
        onKeyUp(event) {
          if (event.defaultPrevented || disabled || event.key !== " ") return;
          if (event.ctrlKey || event.metaKey || event.altKey) return;
          event.preventDefault();
          send({ type: "TRIGGER.KEYDOWN", action: "next" });
        },
      }),

    getValueTextProps: (): T["element"] =>
      normalize.element({
        ...parts.valueText.attrs,
        id: getValueTextId(scope),
        "data-placeholder": dataAttr(!hasValue),
      }),

    // The double chevron. Decoration — the consumer draws an inline SVG in it,
    // never a text glyph, whose baseline would sink the ink below the centre.
    getIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        id: getIndicatorId(scope),
        "aria-hidden": ariaAttr(true),
        "data-state": state,
      }),

    /**
     * The form mirror: a real `<select>`, visually hidden, carrying only the
     * selection (the adapter renders the one `<option>`). Never focusable and
     * never named — the trigger is the control people use; this one is what the
     * form submits, validates and autofills.
     */
    getHiddenSelectProps: (): T["select"] =>
      normalize.select({
        ...parts.hiddenSelect.attrs,
        id: getHiddenSelectId(scope),
        style: visuallyHiddenStyle,
        tabIndex: -1,
        "aria-hidden": ariaAttr(true),
        name: prop("name"),
        form: prop("form"),
        required,
        disabled,
        value: value ?? "",
        onChange(event) {
          // Autofill is the only writer that can reach a hidden mirror; report
          // it into the machine rather than silently diverging from it.
          const mirror = event.currentTarget as HTMLSelectElement | null;
          if (mirror === null) return;
          send({ type: "VALUE.SET", value: mirror.value === "" ? null : mirror.value });
        },
      }),

    getBackdropProps: (): T["element"] =>
      normalize.element({
        ...parts.backdrop.attrs,
        id: getBackdropId(scope),
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        "data-presentation": presentation,
      }),

    /**
     * The floating element. `data-side`/`data-align` are deliberately absent
     * here — the position effect writes onto this node directly, and an adapter
     * that also rendered them would fight it over every commit. They are
     * published on `content`, from `currentPlacement`.
     */
    getPositionerProps: (): T["element"] =>
      normalize.element({
        ...parts.positioner.attrs,
        id: getPositionerId(scope),
        "data-sui-layer-parent": prop("parentId"),
        "data-state": state,
        "data-presentation": presentation,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        id: contentId,
        role: "listbox",
        dir: context.get("surfaceDir") ?? dir,
        tabIndex: -1,
        "aria-orientation": "vertical",
        // The trigger names the surface; an explicit `label` prop wins over it
        // (the menu's arbitrage). Never both.
        "aria-labelledby": prop("label") === undefined ? triggerId : undefined,
        "aria-label": prop("label"),
        "data-state": state,
        "data-presentation": presentation,
        "data-side": side,
        "data-align": align,
        "data-placement": placement,
        // Constant, and constant on purpose: a select always reserves the
        // checkmark gutter, because any row can become the checked one — unlike
        // the menu, which has to detect whether a checkmark exists at all.
        "data-has-selection": "",
        "data-has-symbols": dataAttr(hasSymbols),
        // The surface applies the glass material, so the surface owes
        // its contents the on-glass palette (architecture.md).
        "data-sui-on-glass": "",
        "data-snav": "container",
        "data-snav-enter": "first",
        "data-snav-wrap": prop("loopFocus") ? "y" : undefined,
        "data-snav-trap": prop("modal") ? "" : undefined,
        onKeyDown: onContentKeyDown,
        onKeyUp: onContentKeyUp,
      }),

    getItemGroupProps: (group: SelectItemGroupProps): T["element"] =>
      normalize.element({
        ...parts.itemGroup.attrs,
        id: getItemGroupId(scope, group.id),
        role: "group",
        // Declared, never assumed — written blind it is a dead IDREF and no
        // accessible name at once (the menu's lesson, kept).
        "aria-labelledby": group.label === true ? getItemGroupLabelId(scope, group.id) : undefined,
      }),

    // Not `role="presentation"`: it is referenced by the group's
    // `aria-labelledby`, and a presentational node names nothing.
    getItemGroupLabelProps: (label: SelectItemGroupLabelProps): T["element"] =>
      normalize.element({
        ...parts.itemGroupLabel.attrs,
        id: getItemGroupLabelId(scope, label.htmlFor),
      }),

    getItemProps: (item: SelectItemProps): T["element"] =>
      normalize.element({ ...parts.item.attrs, ...itemProps(item) }),

    getItemTextProps: (): T["element"] => normalize.element({ ...parts.itemText.attrs }),

    // The reserved symbol column, sharing its cell with the checkmark — one
    // leading track, never two (the `_menu.scss` rule, inherited).
    getItemSymbolProps: (): T["element"] =>
      normalize.element({ ...parts.itemSymbol.attrs, "aria-hidden": ariaAttr(true) }),

    // The checkmark. The state is `aria-selected` on the item, never the glyph
    // — so this node is hidden and the two can never disagree.
    getItemIndicatorProps: (indicator: SelectItemIndicatorProps): T["element"] =>
      normalize.element({
        ...parts.itemIndicator.attrs,
        "aria-hidden": ariaAttr(true),
        "data-state": value === indicator.value ? "checked" : "unchecked",
      }),

    /**
     * `role="none"`, a deliberate divergence from the menu's `role="separator"`:
     * a `role="listbox"` owns nothing but options and groups, so a semantic
     * separator inside one is an `aria-required-children` violation. The
     * platform agrees — the `<hr>` HTML allows inside `<select>` is
     * presentational.
     */
    getSeparatorProps: (): T["element"] =>
      normalize.element({
        ...parts.separator.attrs,
        role: "none",
        "aria-hidden": ariaAttr(true),
      }),

    /**
     * Sheet only, and a sibling of the listbox — never inside it, where a bare
     * button would be the same owned-children violation as the separator.
     * `tabindex="-1"`: a pointer/touch affordance whose keyboard and screen
     * reader path is Escape/B (the `tabs:closeTrigger` precedent). Not
     * `aria-hidden` — explore-by-touch must be able to land on it.
     */
    getCancelTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.cancelTrigger.attrs,
        id: getCancelTriggerId(scope),
        type: "button",
        tabIndex: -1,
        "data-state": state,
        "data-presentation": presentation,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CANCEL.CLICK" });
        },
      }),
  };
}

/**
 * **The option collection is read from the live DOM, never held in context** —
 * the menu's doctrine, inherited with the shared reader it was factored into
 * (`collection/dom-collection`, whose header names `select` as the next
 * consumer). What stays here is this component's own selectors and ids.
 */

import {
  getItemLabel as domItemLabel,
  findItemByValue,
  queryItems,
} from "../../collection/dom-collection";
import { contains } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

export { getItemValue, isItemDisabled } from "../../collection/dom-collection";

const COMPONENT = "select";

/**
 * Written out rather than derived from `parts`: the anatomy builds the same
 * strings, and a component that imports its own anatomy into its DOM helpers pays
 * for the builder in every bundle that only wanted a query.
 */
const CONTENT_SELECTOR = '[data-part~="select:content"]';

/**
 * One identity, unlike the menu's three. The sheet's Cancel button is
 * deliberately **not** part of it: an option collection is what a `listbox`
 * owns, the cancel is a sibling of the listbox in the positioner, and folding
 * it in would make `End` land on a control that is not an option.
 */
export const ITEM_SELECTOR = '[data-part~="select:item"]';

const ITEM_TEXT_SELECTOR = '[data-part~="select:item-text"]';
const SYMBOL_SELECTOR = '[data-part~="select:item-symbol"]';

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getValueTextId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "value-text");
}

export function getIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "indicator");
}

export function getHiddenSelectId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "hidden-select");
}

export function getBackdropId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "backdrop");
}

export function getPositionerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "positioner");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getItemGroupId(scope: Scope, key: string): string {
  return getPartId(scope, COMPONENT, "item-group", key);
}

export function getItemGroupLabelId(scope: Scope, key: string): string {
  return getPartId(scope, COMPONENT, "item-group-label", key);
}

export function getItemId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "item", value);
}

export function getCancelTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "cancel-trigger");
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

export function getHiddenSelectEl(scope: Scope): HTMLSelectElement | null {
  return scope.getById<HTMLSelectElement>(getHiddenSelectId(scope));
}

export function getBackdropEl(scope: Scope): HTMLElement | null {
  return scope.getById(getBackdropId(scope));
}

/** The floating element: what gets the translate, never the content. */
export function getPositionerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getPositionerId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

export function getCancelTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getCancelTriggerId(scope));
}

/**
 * This select's own options, in DOM order. The container filter is what a flat
 * query cannot do: a select rendered inside another collection surface must not
 * hand its options to the outer machine, nor adopt anything of its own.
 */
export function getItemEls(scope: Scope): HTMLElement[] {
  return queryItems(getContentEl(scope), ITEM_SELECTOR, CONTENT_SELECTOR);
}

export function getItemEl(scope: Scope, value: string): HTMLElement | null {
  return findItemByValue(getItemEls(scope), value);
}

export function getItemLabel(item: HTMLElement): string {
  return domItemLabel(item, ITEM_TEXT_SELECTOR);
}

/**
 * Whether any row draws a glyph — and therefore whether the symbol track is
 * reserved for **all** of them. The selection gutter has no twin read: a select
 * always reserves it, because any row can become the checked one.
 */
export function hasSymbolGutter(scope: Scope): boolean {
  return queryItems(getContentEl(scope), SYMBOL_SELECTOR, CONTENT_SELECTOR).length > 0;
}

/** Whether the real focus is inside this select's surface — never a virtual one. */
export function ownsFocus(scope: Scope): boolean {
  return contains(getContentEl(scope), scope.getActiveElement());
}

/** Same three fallbacks as the menu: no document, no throw. */
export function getEnvironmentEl(scope: Scope): HTMLElement | null {
  const rendered = getContentEl(scope) ?? getTriggerEl(scope);
  if (rendered !== null) return rendered;
  const root = scope.getRootNode();
  if (root === null) return null;
  return (root.ownerDocument ?? (root as Document)).documentElement;
}

/**
 * A select is the menu's surface with a value: overlay + collection, minus the
 * tree, plus the form. Every structural decision below is the menu's, kept
 * verbatim so the two components cannot drift apart:
 *
 * **Two states, projection of `context.open`** — the dialog/popover/menu
 * doctrine. **The collection is the DOM** (`select.dom.ts`): no `items` prop,
 * no `isEqual`, no registry. **The focus is real**, roving `tabindex` plus
 * `.focus()`, never `aria-activedescendant` — the APG select-only example uses
 * the latter, the Combobox pattern allows the former, and the library's hard
 * rule ("la manette pilote le vrai focus DOM") settles it.
 *
 * What is the select's own: `value`/`valueLabel` (the trigger reflects the
 * selection while the surface is closed, which is why adapters keep the content
 * mounted), the `hiddenSelect` form mirror with its `FORM.RESET` listener, and
 * the APG select-only keyboard grammar (a typed character on the closed trigger
 * opens and highlights, it never selects — the one divergence from the Windows
 * native control, and the APG's side of it).
 */

import { hideOthers } from "../../a11y/aria-hidden";
import { lockScroll } from "../../a11y/scroll-lock";
import { getItemValue, getNextItem, isItemDisabled } from "../../collection/dom-collection";
import { addDomEvent } from "../../dom/event";
import { observeChildren } from "../../dom/observers";
import { contains } from "../../dom/query";
import { timeout } from "../../dom/raf";
import { resolveDir } from "../../dom/text-dir";
import {
  resolveEnvironment,
  trackEnvironment as watchEnvironment,
} from "../../environment/environment";
import { proxyTabFocus } from "../../focus/proxy-tab-focus";
import { restoreFocus } from "../../focus/restore-focus";
import type { RovingAction } from "../../focus/roving-focus";
import { trackDismissableLayer } from "../../interaction/dismissable";
import { getLayerStack, isEscapeLikeDismissal } from "../../interaction/layer-stack";
import { trackScrollEdges as trackEdges } from "../../interaction/scroll-edges";
import { createTypeaheadState, getByTypeahead } from "../../interaction/typeahead";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams, Transition } from "../../machine/types";
import { focusElement, getInputModality, trackInputModality } from "../../nav";
import { trackPosition } from "../../positioner/track-position";
import type { Density, Direction, InputModality } from "../../types";
import { isDev } from "../../utils/env";
import { warn } from "../../utils/invariant";
import {
  getBackdropEl,
  getCancelTriggerEl,
  getContentEl,
  getContentId,
  getEnvironmentEl,
  getHiddenSelectEl,
  getItemEl,
  getItemEls,
  getItemLabel,
  getPositionerEl,
  getTriggerEl,
  hasSymbolGutter,
  ownsFocus,
} from "./select.dom";
import type { SelectSchema } from "./select.types";

type Params = MachineParams<SelectSchema>;

/** The inline properties `trackPosition` writes and never cleans up itself. */
const POSITION_STYLES = ["position", "top", "left", "transform", "width"] as const;

/**
 * `2 × --sui-duration-75`, the selection blink — the menu's constant,
 * restated for the menu's reason: the machine must not depend on a stylesheet
 * being loaded, and the deferral it buys the close is behaviour, not decoration.
 */
const FLASH_DURATION_MS = 150;

/**
 * How long after an opening press a click on the same trigger is *not* a toggle.
 * Press-drag-release: the pointer goes down, the select opens, and the release
 * that follows on the trigger must leave it open.
 */
const REOPEN_GRACE_MS = 300;

function windowOf({ scope }: Params): (Window & typeof globalThis) | null {
  return getContentEl(scope)?.ownerDocument.defaultView ?? null;
}

/**
 * The trigger's name, read the three ways it can arrive — and that is the whole
 * list, because `role="combobox"` takes none from its contents: the contents are
 * the *value* (`select.connect.ts`, `getTriggerProps`, where the same violation
 * is named).
 *
 * `labels` is the DOM's own answer to both `<label for>` and an enclosing
 * `<label>`, which is how a `field` above names this control — it hands the
 * trigger its control id and lets the association be native, so there is no
 * IDREF here to read. It is absent when the trigger was substituted for something
 * unlabelable, where only the ancestor form can apply anyway.
 */
function hasAccessibleName(node: HTMLElement): boolean {
  if (node.hasAttribute("aria-label") || node.hasAttribute("aria-labelledby")) return true;
  const labels = (node as Partial<HTMLButtonElement>).labels;
  if (labels !== undefined && labels !== null) return labels.length > 0;
  return node.closest("label") !== null;
}

/** The one place `highlightedValue` is written, so the modality is never forgotten. */
function commitHighlight(params: Params, value: string | null): void {
  const { context, scope } = params;
  if (scope.getRootNode() !== null) {
    context.set("focusSource", value === null ? null : getInputModality(scope.getDoc()));
  }
  context.set("highlightedValue", value);
}

/**
 * The focus is real, always — and, past the ceiling of a capped surface, the
 * reveal is put back by hand, because `focusElement`'s `preventScroll` also
 * suppresses the user agent's own (the menu's WCAG 2.4.11 guard, kept).
 */
function focusHighlightedItem({ context, scope }: Params): void {
  const value = context.get("highlightedValue");
  if (value === null) return;
  const item = getItemEl(scope, value);
  focusElement(item);
  if (item === null) return;
  const content = getContentEl(scope);
  if (content === null || content.scrollHeight <= content.clientHeight) return;
  item.scrollIntoView({
    block: "nearest",
    inline: "nearest",
    behavior: resolveEnvironment(content).reducedMotion ? "auto" : "smooth",
  });
}

/**
 * Disabled items are stepped over rather than focused — APG allows either, and
 * the library already chose skipping in the menu and the radio group.
 */
function applyRoving(params: Params, action: RovingAction): void {
  const { context, prop, scope } = params;
  const target = getNextItem(
    getItemEls(scope),
    context.get("highlightedValue"),
    action,
    prop("loopFocus"),
  );
  if (target !== null) commitHighlight(params, getItemValue(target));
}

/**
 * A page is ten options, the number the APG's own select-only example uses, and
 * it is clamped rather than wrapped: PageDown at the bottom of a list stays at
 * the bottom, where `ArrowDown` with `loopFocus` would come back to the top.
 * Paging is a reading gesture, and a reader who hits the end wants to know it.
 */
const PAGE_SIZE = 10;

/**
 * The optional half of the APG select-only table, and it is not optional here.
 * The claim it replaces — "the focus is real and inside the scroller, so the
 * browser pages the list itself" — is half true and therefore wrong: the browser
 * does scroll the scroller, and it leaves the roving tabindex exactly where it
 * was. The highlight then sits off-screen, the next arrow key jumps the view
 * back, and nothing the user did is undone by anything they can see.
 */
function applyPage(params: Params, direction: "next" | "prev"): void {
  const { context, scope } = params;
  const items = getItemEls(scope);
  if (items.length === 0) return;

  const current = context.get("highlightedValue");
  const from = current === null ? -1 : items.findIndex((item) => getItemValue(item) === current);
  const step = direction === "next" ? PAGE_SIZE : -PAGE_SIZE;
  // From an empty highlight a page lands at the end it came from, which is what
  // the first ArrowDown/ArrowUp does too.
  const wanted = from === -1 ? (direction === "next" ? items.length - 1 : 0) : from + step;
  const target = Math.min(Math.max(wanted, 0), items.length - 1);

  // Enabled items only, scanning back towards where the focus came from: a
  // disabled option at the landing spot must not swallow the whole gesture.
  const back = target > from ? -1 : 1;
  for (let index = target; index >= 0 && index < items.length; index += back) {
    const item = items[index];
    if (item === undefined || isItemDisabled(item)) continue;
    commitHighlight(params, getItemValue(item));
    return;
  }
}

function applyTypeahead(params: Params, key: string): void {
  const { context, refs, scope } = params;
  const items = getItemEls(scope);
  const value = context.get("highlightedValue");
  const match = getByTypeahead(refs.get("typeahead"), key, {
    items,
    itemToString: getItemLabel,
    isItemDisabled,
    activeIndex: items.findIndex((item) => getItemValue(item) === value),
  });
  if (match !== null) commitHighlight(params, getItemValue(match));
}

function openSurface(params: Params): void {
  const { context, refs, event } = params;
  if (event.type === "TRIGGER.KEYDOWN") refs.set("pendingHighlight", event.action);
  refs.set("openedAt", Date.now());
  context.set("open", true);
}

/** The item an event names — the click's value, or the hover's. */
function eventValue({ event }: Params): string | null {
  if (event.type === "ITEM.CLICK" || event.type === "ITEM.POINTERMOVE") return event.value;
  return null;
}

/**
 * Enabled unless the DOM says otherwise. Leaner than the menu's guard on
 * purpose: an `ITEM.*` event only ever originates from a rendered item's own
 * handler, so an unresolvable item is the node-harness case, not a user's — and
 * refusing there would make the machine's pure half untestable. The refusal of
 * a *disabled* item is what matters, and the DOM answers it whenever there is one.
 */
function isEventItemEnabled(params: Params): boolean {
  if (params.prop("disabled")) return false;
  const value = eventValue(params);
  if (value === null) return false;
  const item = getItemEl(params.scope, value);
  return item === null || !isItemDisabled(item);
}

/**
 * The commit, and only the commit: `context.value` moves (the bindable emits
 * `onValueChange` without writing when controlled) and the label follows through
 * `syncCollection`, which the `value` watcher triggers — one writer for the
 * label, so a controlled consumer who declines the change cannot end up with a
 * caption for a value they refused.
 */
function commitValue({ context, event }: Params): void {
  if (event.type === "ITEM.CLICK") context.set("value", event.value);
}

/**
 * Three branches, one array. Unlike the menu there is no per-item
 * `closeOnSelect` and no trigger item — the surface settles it alone.
 */
const SELECT_TRANSITIONS: Transition<SelectSchema> = [
  { guard: "shouldFlash", actions: ["selectItem", "flashSelection"] },
  { guard: "shouldCloseOnSelect", actions: ["selectItem", "closeSelect"] },
  { guard: "isItemEnabled", actions: ["selectItem"] },
];

export const machine: Machine<SelectSchema> = createMachine<SelectSchema>({
  props({ props }) {
    return {
      defaultValue: null,
      defaultOpen: false,
      presentation: "auto",
      // A simple default, not a computed: a select has no submenu to re-aim for.
      placement: "bottom-start",
      gap: 4,
      offset: 0,
      flip: true,
      shift: true,
      padding: 8,
      // The select's divergence from the menu (ROADMAP): the surface is never
      // narrower than its trigger. A floor, not an identity — the ROADMAP asks
      // for the feature, and native desktop pop-up menus are 18-40px wider
      // than their buttons, so clamping down would only truncate the rows.
      matchWidth: true,
      strategy: "fixed",
      loopFocus: true,
      typeahead: true,
      closeOnSelect: true,
      closeOnEscape: true,
      closeOnInteractOutside: true,
      preventOutsideActivation: true,
      modal: false,
      restoreFocus: true,
      required: false,
      invalid: false,
      disabled: false,
      selectionFlash: true,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      open: bindable<boolean>(() => ({
        defaultValue: prop("defaultOpen"),
        value: prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "select open",
      })),
      value: bindable<string | null>(() => ({
        defaultValue: prop("defaultValue"),
        value: prop("value"),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "select value",
      })),
      valueLabel: bindable<string | null>(() => ({ defaultValue: null })),
      highlightedValue: bindable<string | null>(() => ({
        defaultValue: prop("defaultHighlightedValue") ?? null,
        value: prop("highlightedValue"),
        onChange: (value) => prop("onHighlightChange")?.({ value }),
        debugLabel: "select highlightedValue",
      })),
      density: bindable<Density>(() => ({ defaultValue: "desktop" })),
      surfaceDir: bindable<Direction | null>(() => ({ defaultValue: null })),
      currentPlacement: bindable(() => ({ defaultValue: prop("placement") })),
      hasSymbolGutter: bindable<boolean>(() => ({ defaultValue: false })),
      flashingValue: bindable<string | null>(() => ({ defaultValue: null })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  computed: {
    presentation({ prop, context }) {
      const requested = prop("presentation");
      if (requested !== "auto") return requested;
      return context.get("density") === "touch" ? "sheet" : "popup";
    },
    hasValue: ({ context }) => context.get("value") !== null,
  },

  refs({ prop }) {
    const controlled = prop("value");
    return {
      finalFocusEl: null,
      typeahead: createTypeaheadState(),
      pendingTypeaheadKey: null,
      pendingHighlight: null,
      flashTimer: null,
      openedAt: 0,
      closedByCommit: false,
      // `??` would fold an explicitly controlled `null` onto the default.
      initialValue: controlled === undefined ? prop("defaultValue") : controlled,
      labelValue: null,
    };
  },

  initialState({ prop }) {
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: ["trackEnvironment", "trackModality", "trackCollection", "trackFormReset"],

  watch({ context, computed, scope, track, send, action }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
    track(
      () => [computed("presentation")],
      () => send({ type: "PRESENTATION.SYNC" }),
    );
    // The collection is the DOM, so the DOM is a watch dependency: a content
    // that mounts late, a value that changes, a label that finally exists and a
    // glyph column that appears are all re-read on the adapter's next commit.
    track(
      () => {
        const value = context.get("value");
        const item = value === null ? null : getItemEl(scope, value);
        return [
          value,
          item === null ? null : getItemLabel(item),
          hasSymbolGutter(scope),
          getContentEl(scope) !== null,
        ];
      },
      () => action(["syncCollection"]),
    );
  },

  on: {
    "HIGHLIGHT.SET": { actions: ["highlightItem", "focusHighlighted"] },
    "VALUE.SET": { actions: ["setValue"] },
    "POSITION.SYNC": { actions: ["syncPlacement"] },
    "OPEN.SET": { actions: ["setOpen"] },
    "OPEN.SYNC": [{ guard: "isOpen", target: "open" }, { target: "closed" }],
    // The density flip tears the open state down and builds it back: the
    // position tracker leaves, the scroll lock arrives, the geometry changes.
    //
    // It also replays the two focus-moving pieces: `focusContent`'s install, and
    // the entry `highlightInitial`, whose `focusHighlightedItem` calls
    // `focusElement(item)` without ever reading the active element. So a live
    // density flip puts the focus back on the highlighted item whatever a person
    // was doing. `date-picker` gates both on the event — the teardown half
    // included, since the disposer would otherwise yank focus from the other end —
    // and it was fixed there first because its segmented field sits *outside* the
    // surface, so even the disposer's `contains` guard never saw the victim. A
    // select's surface holds everything a person can be doing inside it, which
    // makes this the quiet case, not the absent one. Named debt (audit of
    // 2026-09-06): the same gate belongs here, and the two files settle together.
    "PRESENTATION.SYNC": { guard: "isOpen", target: "open", reenter: true },
    "ENVIRONMENT.SYNC": { actions: ["syncEnvironment"] },
    "COLLECTION.SYNC": { actions: ["syncCollection"] },
    "FORM.RESET": { actions: ["resetToInitialValue"] },
  },

  states: {
    closed: {
      entry: ["clearTransient"],
      // Exit rather than the open state's entry, for the menu's reason: the
      // interpreter installs effects before entry actions, and an effect that
      // hides or moves things would blur the trigger before it was captured.
      exit: ["captureFinalFocus"],
      on: {
        "TRIGGER.CLICK": { guard: "isEnabled", actions: ["openSelect"] },
        "TRIGGER.POINTERDOWN": { guard: "isEnabled", actions: ["openSelect"] },
        "TRIGGER.KEYDOWN": { guard: "isEnabled", actions: ["openSelect"] },
        // APG select-only: a printable character on the closed trigger opens and
        // highlights the first match. It never selects while closed — the
        // deliberate divergence from the Windows native control.
        "TYPEAHEAD.KEY": {
          guard: "isTypeaheadEnabled",
          actions: ["deferTypeaheadKey", "openSelect"],
        },
      },
    },
    open: {
      entry: ["highlightInitial"],
      effects: [
        "trackSurfaceDir",
        "trackDismissable",
        "lockPageScroll",
        // Before anything that moves the focus. A focus landing in a surface
        // still parked at `0,0` scrolls the page there to reveal it.
        "trackAnchorPosition",
        "focusContent",
        "proxyTabs",
        "hideOutside",
        "captureIntents",
        "trackSelectionFlash",
        "trackScrollEdges",
      ],
      on: {
        // The release of the press that opened it is not a toggle.
        "TRIGGER.CLICK": [{ guard: "isWithinReopenGrace" }, { actions: ["closeSelect"] }],
        "ITEM.POINTERMOVE": {
          guard: "isItemEnabled",
          actions: ["highlightItem", "focusHighlighted"],
        },
        "ITEM.POINTERLEAVE": { guard: "isLeavingHighlighted", actions: ["clearHighlight"] },
        "ITEM.CLICK": SELECT_TRANSITIONS,
        // Enter, Space and the A button. It clicks the element rather than
        // shortcutting to the commit, so a keyboard activation and a pointer one
        // run exactly the same handlers (the menu's arrangement).
        "ITEM.ACTIVATE": { guard: "hasHighlight", actions: ["activateHighlighted"] },
        // Tab and Alt+ArrowUp. Not routed through the item's own click like
        // `ITEM.ACTIVATE` above, and the difference is the blink: both of these
        // move the focus out in the same gesture, so holding the surface open
        // for 150ms would blink a row nobody is looking at — and Tab's proxy
        // would take the focus out from under it while it did.
        "ITEM.COMMIT": [
          { guard: "hasHighlight", actions: ["commitHighlighted", "closeSelect"] },
          // Nothing highlighted is still a close: the gesture is "leave", and a
          // guard that only committed would leave the surface open behind a Tab
          // whose focus has already gone.
          { actions: ["closeSelect"] },
        ],
        "HIGHLIGHT.MOVE": { actions: ["moveHighlight", "focusHighlighted"] },
        "HIGHLIGHT.PAGE": { actions: ["pageHighlight", "focusHighlighted"] },
        "TYPEAHEAD.KEY": {
          guard: "isTypeaheadEnabled",
          actions: ["typeaheadHighlight", "focusHighlighted"],
        },
        "FLASH.END": { actions: ["clearFlash", "closeSelect"] },
        // Never a commit: Escape, an outside press and B all leave the value alone.
        "CONTENT.DISMISS": { guard: "canDismiss", actions: ["invokeOnDismiss", "closeSelect"] },
        "CANCEL.CLICK": { actions: ["invokeOnDismiss", "closeSelect"] },
      },
    },
  },

  implementations: {
    guards: {
      isEnabled: ({ prop }) => !prop("disabled"),
      isOpen: ({ context }) => context.get("open"),
      isItemEnabled: isEventItemEnabled,
      hasHighlight: ({ context, prop }) =>
        !prop("disabled") && context.get("highlightedValue") !== null,
      isLeavingHighlighted: ({ context, event }) =>
        event.type === "ITEM.POINTERLEAVE" && event.value === context.get("highlightedValue"),

      /** Read live from the props, never snapshotted into the layer at install. */
      canDismiss({ prop, event }) {
        if (event.type !== "CONTENT.DISMISS") return false;
        if (isEscapeLikeDismissal(event.reason)) return prop("closeOnEscape");
        return prop("closeOnInteractOutside");
      },

      shouldCloseOnSelect(params) {
        return isEventItemEnabled(params) && params.prop("closeOnSelect");
      },

      /**
       * The blink only exists where it means something: a popup on a desktop
       * that is about to close — and through `resolveEnvironment`, so an app
       * pinned to `data-motion` keeps its own answer.
       */
      shouldFlash(params) {
        const { prop, computed, scope } = params;
        if (!prop("selectionFlash") || !prop("closeOnSelect")) return false;
        if (computed("presentation") !== "popup") return false;
        if (!isEventItemEnabled(params)) return false;
        return !resolveEnvironment(getContentEl(scope)).reducedMotion;
      },

      isTypeaheadEnabled: ({ prop }) => prop("typeahead") && !prop("disabled"),

      isWithinReopenGrace({ refs }) {
        const openedAt = refs.get("openedAt");
        return openedAt !== 0 && Date.now() - openedAt < REOPEN_GRACE_MS;
      },
    },

    actions: {
      openSelect: openSurface,

      closeSelect({ context, refs, event }) {
        refs.set("closedByCommit", event.type === "ITEM.COMMIT");
        context.set("open", false);
      },

      setOpen({ context, event }) {
        if (event.type === "OPEN.SET") context.set("open", event.open);
      },

      captureFinalFocus({ refs, scope }) {
        const active = scope.getActiveElement();
        refs.set("finalFocusEl", active === null || active.tagName === "BODY" ? null : active);
      },

      /**
       * The closed state starts clean: whatever a keystroke asked for on the way
       * in is void once the surface is gone, and the highlight goes with it.
       * Guarded on the *previous* state so the machine's very first entry cannot
       * erase a `defaultHighlightedValue` nobody has consumed yet.
       */
      clearTransient(params) {
        const { refs, state } = params;
        refs.set("pendingHighlight", null);
        refs.set("pendingTypeaheadKey", null);
        if (state.previous() === "open") commitHighlight(params, null);
      },

      /**
       * Runs as the open state's **entry** — after the effects, after the
       * adapter has painted — so the items exist and every request the trigger
       * recorded can finally be honoured, in priority order: the keystroke that
       * opened the surface, then Home/End (which force an end even past a
       * selection), then the selected item, then the end the arrow key named.
       *
       * The deferred typeahead key is consumed here rather than replayed by
       * `focusContent`, and the ordering is the reason: effects install before
       * entry actions, so a replay from the effect would be overwritten by this
       * very action a moment later.
       */
      highlightInitial(params) {
        const { context, refs, scope } = params;
        const key = refs.get("pendingTypeaheadKey");
        refs.set("pendingTypeaheadKey", null);
        if (key !== null) {
          applyTypeahead(params, key);
          focusHighlightedItem(params);
          return;
        }
        const pending = refs.get("pendingHighlight");
        refs.set("pendingHighlight", null);
        if (pending === "first" || pending === "last") {
          applyRoving(params, pending);
          focusHighlightedItem(params);
          return;
        }
        const value = context.get("value");
        const selected = value === null ? null : getItemEl(scope, value);
        if (selected !== null && !isItemDisabled(selected)) {
          commitHighlight(params, value);
        } else {
          applyRoving(params, pending ?? "next");
        }
        focusHighlightedItem(params);
      },

      highlightItem(params) {
        const { event } = params;
        if (event.type === "ITEM.POINTERMOVE") {
          commitHighlight(params, event.value);
          return;
        }
        if (event.type === "HIGHLIGHT.SET") commitHighlight(params, event.value);
      },

      clearHighlight(params) {
        commitHighlight(params, null);
      },

      moveHighlight(params) {
        if (params.event.type === "HIGHLIGHT.MOVE") applyRoving(params, params.event.action);
      },

      pageHighlight(params) {
        if (params.event.type === "HIGHLIGHT.PAGE") applyPage(params, params.event.direction);
      },

      focusHighlighted: focusHighlightedItem,

      typeaheadHighlight(params) {
        if (params.event.type === "TYPEAHEAD.KEY") applyTypeahead(params, params.event.key);
      },

      deferTypeaheadKey({ refs, event }) {
        if (event.type === "TYPEAHEAD.KEY") refs.set("pendingTypeaheadKey", event.key);
      },

      selectItem: commitValue,

      /**
       * The same commit as `selectItem`, from the highlight rather than from a
       * click event. Written out rather than folded into `commitValue` because
       * the disabled check has no click to have already made it.
       */
      commitHighlighted({ context, prop, scope }) {
        if (prop("disabled")) return;
        const value = context.get("highlightedValue");
        if (value === null) return;
        const item = getItemEl(scope, value);
        if (item !== null && isItemDisabled(item)) return;
        context.set("value", value);
      },

      activateHighlighted({ context, prop, scope }) {
        if (prop("disabled")) return;
        const value = context.get("highlightedValue");
        if (value === null) return;
        const item = getItemEl(scope, value);
        if (item === null || isItemDisabled(item)) return;
        item.click();
      },

      /**
       * The blink owns the close: `FLASH.END` is what finally calls
       * `closeSelect`. The timer is cancelled by `trackSelectionFlash`'s
       * disposer — a select dismissed mid-blink would otherwise fire into a
       * surface that has already left.
       */
      flashSelection(params) {
        const { context, refs, event, send } = params;
        if (event.type !== "ITEM.CLICK") return;
        refs.get("flashTimer")?.();
        context.set("flashingValue", event.value);
        const win = windowOf(params);
        if (win === null) {
          send({ type: "FLASH.END" });
          return;
        }
        refs.set(
          "flashTimer",
          timeout(
            win,
            () => {
              refs.set("flashTimer", null);
              send({ type: "FLASH.END" });
            },
            FLASH_DURATION_MS,
          ),
        );
      },

      clearFlash({ context, refs }) {
        refs.get("flashTimer")?.();
        refs.set("flashTimer", null);
        context.set("flashingValue", null);
      },

      /**
       * One action for both ways out that are not a commit. The cancel button is
       * the touch twin of the B button, so it reports the same reason — the
       * layer-stack vocabulary has no "cancel", and inventing one would be a
       * change to another component's contract.
       */
      invokeOnDismiss({ prop, event }) {
        if (event.type === "CONTENT.DISMISS") prop("onDismiss")?.({ reason: event.reason });
        if (event.type === "CANCEL.CLICK") prop("onDismiss")?.({ reason: "back" });
      },

      /** `api.setValue` — the value moves, `open` never does. */
      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("value", event.value);
      },

      resetToInitialValue({ context, refs }) {
        context.set("value", refs.get("initialValue"));
      },

      syncEnvironment({ context, event }) {
        if (event.type === "ENVIRONMENT.SYNC") context.set("density", event.density);
      },

      syncPlacement({ context, event }) {
        if (event.type === "POSITION.SYNC") context.set("currentPlacement", event.placement);
      },

      /**
       * The one writer of `valueLabel`, so its three rules cannot contradict
       * each other: a `null` value clears it; a value whose item is rendered
       * captures the live label; a value whose item is *gone* keeps the last
       * capture — but only when it is a capture *of that value*. A value the
       * DOM has never answered for gets `null`, not a caption borrowed from
       * whatever was selected before.
       */
      syncCollection({ context, refs, scope }) {
        context.set("hasSymbolGutter", hasSymbolGutter(scope));
        const value = context.get("value");
        if (value === null) {
          refs.set("labelValue", null);
          context.set("valueLabel", null);
          return;
        }
        const item = getItemEl(scope, value);
        if (item !== null) {
          refs.set("labelValue", value);
          context.set("valueLabel", getItemLabel(item));
          return;
        }
        if (refs.get("labelValue") !== value) context.set("valueLabel", null);
      },
    },

    effects: {
      trackEnvironment({ scope, send }) {
        const node = getEnvironmentEl(scope);
        const onChange = (density: Density): void => send({ type: "ENVIRONMENT.SYNC", density });
        onChange(resolveEnvironment(node).density);
        return watchEnvironment(node, {
          onChange: (environment) => onChange(environment.density),
        });
      },

      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      /**
       * Machine level, not open level, and that is the whole point of the
       * always-mounted content: the closed trigger shows the selected label, the
       * closed typeahead finds the items, and the form mirror knows what it
       * carries — three reads that need the collection while nothing is open.
       */
      trackCollection({ scope, send }) {
        send({ type: "COLLECTION.SYNC" });
        // Said here, where the collection is already being read, and said once:
        // `role="combobox"` demands a name and this component cannot invent one.
        // The menu makes the twin call for the surface it cannot name
        // (`menu.machine.ts`, `trackParts`). No deferral, unlike the slider's: the
        // name a `field` supplies is the trigger's own control id, written during
        // the render that commits both elements, not by an effect that runs after
        // this one. **Absent is not nameless** — nothing is rendered on a server,
        // and warning then would fire on every tree before its first paint.
        const trigger = getTriggerEl(scope);
        warn(
          isDev() && trigger !== null && !hasAccessibleName(trigger),
          "a select has no accessible name — pass `label` or `labelledBy`, or render it inside a `field`",
        );
        const content = getContentEl(scope);
        if (content === null) return;
        return observeChildren(content, () => send({ type: "COLLECTION.SYNC" }));
      },

      /**
       * The native `reset` runs first (`timeout 0`), then the machine follows it
       * — so the mirror and the trigger agree with the form instead of racing
       * it. The owner form is the mirror's own `form` property, which already
       * resolves both the attribute and the ancestor.
       */
      trackFormReset({ scope, send }) {
        const mirror = getHiddenSelectEl(scope);
        const form = mirror?.form ?? null;
        const win = form?.ownerDocument.defaultView ?? null;
        if (form === null || win === null) return;
        let cancel: VoidFunction | null = null;
        const remove = addDomEvent(form, "reset", () => {
          cancel?.();
          cancel = timeout(
            win,
            () => {
              cancel = null;
              send({ type: "FORM.RESET" });
            },
            0,
          );
        });
        return () => {
          cancel?.();
          remove();
        };
      },

      /**
       * Parity M5, inherited whole from the menu: `preventOutsideActivation`
       * makes the click that closes a select stop there instead of activating
       * what was underneath. The swallow logic lives in the shared layer options
       * — see `menu.machine.ts` for the archaeology of the one-shot listener.
       */
      trackDismissable({ prop, scope, send }) {
        const content = getContentEl(scope);
        const doc = content?.ownerDocument;
        const win = doc?.defaultView ?? null;

        return trackDismissableLayer(content, {
          id: getContentId(scope),
          type: "listbox",
          modal: prop("modal"),
          parentId: prop("parentId"),
          // The sheet's cancel too: it sits beside the listbox, so a press on it
          // was outside and reported `outside-pointer` instead of its own `back`
          // (R59). The cancel alone and not the positioner, whose box no stylesheet
          // is trusted to keep out of the pointer's way (decision 01).
          exclude: () => [
            getTriggerEl(scope),
            getCancelTriggerEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          onPointerDownOutside(event) {
            if (!prop("preventOutsideActivation") || doc === undefined || win === null) return;
            event.preventDefault();
            let cancelFuse: VoidFunction | undefined;
            const removeClick = addDomEvent(
              doc,
              "click",
              (click) => {
                click.preventDefault();
                click.stopPropagation();
                cancelFuse?.();
              },
              { capture: true, once: true },
            );
            // A trusted click follows its own pointerup within a frame; the fuse
            // only exists so a gesture that ended in a drag cannot leave a
            // listener waiting for a click nobody meant.
            cancelFuse = timeout(win, removeClick, REOPEN_GRACE_MS);
          },
          onDismiss: (reason) => send({ type: "CONTENT.DISMISS", reason }),
        });
      },

      lockPageScroll({ prop, computed, scope }) {
        if (computed("presentation") !== "sheet") return;
        if (prop("preventScroll") === false) return;
        return lockScroll(getContentEl(scope)?.ownerDocument);
      },

      /**
       * The sheet branch clears what a previous popup pass left behind, on
       * install rather than on teardown: a disposer would run while `presence`
       * still holds the node for its exit, and the surface would snap to `0,0`
       * mid-fade.
       */
      /**
       * The surface is the one part that emits a `dir` nobody asked for,
       * and the portal is the whole reason. The adapter mounts it into
       * `document.body` (react/src/portal.tsx), outside whatever RTL region the
       * trigger sits in, and inheritance does not cross a portal — so the
       * direction has to be carried over explicitly. What was removed everywhere is the
       * ltr DEFAULT, not the attribute: a part still emits `dir` when the consumer
       * passes one. The default was the bug — emitting a direction nobody asked
       * for *overrode* the inheritance that already worked.
       *
       * Read from the anchor, never from the surface: the surface is in the body
       * and would only report the document's own direction back to itself. And in
       * an effect rather than in `connect`, so the server emits nothing and the
       * first client render has nothing to disagree with.
       */
      trackSurfaceDir({ prop, context, scope }) {
        context.set("surfaceDir", resolveDir(prop("dir"), getTriggerEl(scope)));
      },

      trackAnchorPosition({ prop, context, computed, scope, send }) {
        const positioner = getPositionerEl(scope);
        if (positioner === null) return;

        if (computed("presentation") !== "popup") {
          for (const name of POSITION_STYLES) positioner.style.removeProperty(name);
          positioner.style.removeProperty("--sui-transform-origin");
          return;
        }

        return trackPosition(getTriggerEl(scope), positioner, {
          placement: prop("placement"),
          gap: prop("gap"),
          offset: prop("offset"),
          flip: prop("flip"),
          shift: prop("shift"),
          padding: prop("padding"),
          matchWidth: prop("matchWidth"),
          // From the trigger, not from the surface: the surface is portalled into
          // `document.body` and would report the document direction, while the
          // alignment belongs to the region the trigger sits in.
          dir: resolveDir(prop("dir"), getTriggerEl(scope)),
          strategy: prop("strategy"),
          boundary: prop("boundary"),
          getAnchorRect: prop("getAnchorRect"),
          // Frozen for the length of the blink, and only there. The commit is
          // synchronous: `value` moves, `syncCollection` rewrites `valueLabel`,
          // the trigger's caption changes and the trigger resizes — while
          // `flashSelection` still holds the surface open for 150ms. Without
          // this, the `ResizeObserver` re-fits a fully opaque surface one frame
          // before it fades, which is the "truc chelou" of the review. Every
          // other way out closes in the same transition, so this effect's
          // disposer has already stopped the tracker by the observer's next
          // frame; and with `closeOnSelect` off there is no flash at all, so the
          // surface goes on tracking its new trigger, which is what it owes.
          paused: () => context.get("flashingValue") !== null,
          onPositioned: (result) => send({ type: "POSITION.SYNC", placement: result.placement }),
        });
      },

      /**
       * The surface takes the focus so the keys reach it; `highlightInitial`
       * moves it onto an item straight after, from the open state's entry.
       *
       * The disposer is the restore, and it only fires when the focus is still
       * inside: a person who left by clicking elsewhere, or by tabbing past the
       * trigger, has already said where they want to be. Inside the positioner,
       * not the listbox: a press on the sheet's cancel beside it focuses the cancel.
       * A trigger disabled while open takes nothing, so `restoreFocus` falls back
       * on its neighbour (R61).
       */
      focusContent({ prop, refs, scope }) {
        const content = getContentEl(scope);
        if (content === null) return;
        const layer = getPositionerEl(scope) ?? content;
        focusElement(content);
        return () => {
          if (!prop("restoreFocus")) return;
          if (!contains(layer, scope.getActiveElement())) return;
          const target = prop("finalFocus")?.() ?? refs.get("finalFocusEl") ?? getTriggerEl(scope);
          restoreFocus(target, layer);
        };
      },

      /**
       * Tab out of the portalled surface lands after the trigger — and the
       * connect's own Tab handling has already closed the select without a
       * commit before this proxy carries the focus on (APG select-only).
       *
       * Modal: the step waits for this disposer. Effects tear down in reverse,
       * so `hideOutside` has released the page by then and the trigger and its
       * neighbours are focusable again; `focusContent`'s restore runs after and
       * finds the focus already out. Placed only when the surface is really
       * closing and by the commit the Tab asked for: a parent that refused that
       * close, then closed for Escape or a click, owes the trigger, and a
       * `reenter` keeps the surface open.
       */
      proxyTabs({ prop, context, refs, scope }) {
        return proxyTabFocus(getContentEl(scope), {
          triggerNode: () => getTriggerEl(scope),
          placeOnDispose: prop("modal")
            ? () => !context.get("open") && refs.get("closedByCommit")
            : undefined,
        });
      },

      hideOutside({ prop, scope }) {
        if (!prop("modal")) return;
        return hideOthers(
          [
            getContentEl(scope),
            getPositionerEl(scope),
            getBackdropEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          { inert: true },
        );
      },

      /**
       * Not `trapped` — the popover's reason, kept: a trapped scope silences the
       * spatial engine at the bottom of the stack and makes the select's own
       * interior unreachable to a d-pad.
       *
       * The claimed set is deliberately narrow (components.md: « A ouvre,
       * D-pad, A choisit, B annule ») — `moveLeft`/`moveRight`, X, Y, the page
       * intents and the scroll stick all pass through, because the real focus
       * is inside the scroller and the platform already answers them.
       */
      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        const content = getContentEl(scope);
        if (host === null || host === undefined || content === null) return;
        const id = getContentId(scope);
        const stack = getLayerStack(content.ownerDocument);

        return host.pushScope((event) => {
          if (event.intent === "back") {
            if (!prop("closeOnEscape") || !stack.isTopMost(id)) return false;
            send({ type: "CONTENT.DISMISS", reason: "back" });
            return true;
          }
          if (!ownsFocus(scope)) return false;
          if (event.intent === "select") {
            send({ type: "ITEM.ACTIVATE" });
            return true;
          }
          if (event.intent === "moveDown") {
            send({ type: "HIGHLIGHT.MOVE", action: "next" });
            return true;
          }
          if (event.intent === "moveUp") {
            send({ type: "HIGHLIGHT.MOVE", action: "prev" });
            return true;
          }
          return false;
        });
      },

      /** See `flashSelection` — this effect exists for its disposer. */
      trackSelectionFlash({ refs, context }) {
        return () => {
          refs.get("flashTimer")?.();
          refs.set("flashTimer", null);
          context.set("flashingValue", null);
        };
      },

      /**
       * `data-scroll` on the scroller, written straight onto the node — the
       * shared affordance the menu introduced, and the select is its second
       * consumer. Never conditioned on reduced motion: it is not an animation,
       * it is the only indication that there is more list.
       */
      trackScrollEdges({ scope }) {
        return trackEdges(getContentEl(scope));
      },
    },
  },
});

import type { RovingAction } from "../../focus/roving-focus";
import type { DismissReason } from "../../interaction/layer-stack";
import type { TypeaheadState } from "../../interaction/typeahead";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Placement } from "../../positioner/compute-position";
import type { Density, Direction, InputModality, Rect } from "../../types";

/** What the surface actually is once the density has had its say. */
export type SelectPresentation = "popup" | "sheet";

export type SelectPresentationProp = "auto" | SelectPresentation;

export interface SelectValueChangeDetails {
  readonly value: string | null;
}

export interface SelectOpenChangeDetails {
  readonly open: boolean;
}

export interface SelectHighlightChangeDetails {
  readonly value: string | null;
}

export interface SelectDismissDetails {
  readonly reason: DismissReason;
}

export interface SelectMachineProps {
  // --- value -----------------------------------------------------------------
  /** Single, `string | null`. Multi-select is `listbox`/`combobox` territory. */
  readonly value?: string | null | undefined;
  readonly defaultValue?: string | null | undefined;
  readonly onValueChange?: ((details: SelectValueChangeDetails) => void) | undefined;

  // --- openness --------------------------------------------------------------
  /** Controlled. */
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  readonly onOpenChange?: ((details: SelectOpenChangeDetails) => void) | undefined;
  /** Defaults to `auto`, which the density resolves into `popup` or `sheet`. */
  readonly presentation?: SelectPresentationProp | undefined;

  // --- positioning, handed straight to the positioner ------------------------
  readonly placement?: Placement | undefined;
  readonly gap?: number | undefined;
  readonly offset?: number | undefined;
  readonly flip?: boolean | undefined;
  readonly shift?: boolean | undefined;
  readonly padding?: number | undefined;
  /**
   * `true` by default — the select's divergence from the menu (ROADMAP): a
   * surface of options is a widened trigger, so its width is the anchor's.
   */
  readonly matchWidth?: boolean | undefined;
  readonly strategy?: "absolute" | "fixed" | undefined;
  readonly boundary?: (() => Rect) | undefined;
  /** Anchor to a rect rather than an element — a caret, a canvas, a cell. */
  readonly getAnchorRect?: (() => Rect) | undefined;

  // --- collection ------------------------------------------------------------
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly loopFocus?: boolean | undefined;
  readonly typeahead?: boolean | undefined;
  /**
   * No per-item override, a deliberate divergence from the menu: a select that
   * stays open after a choice is a setting of the surface, not of one item.
   */
  readonly closeOnSelect?: boolean | undefined;
  /** The keyboard cursor, not the selection: arrows and typeahead move it, and `value` only follows once a choice is committed. */
  readonly highlightedValue?: string | null | undefined;
  readonly defaultHighlightedValue?: string | null | undefined;
  readonly onHighlightChange?: ((details: SelectHighlightChangeDetails) => void) | undefined;

  // --- dismissal (the menu's defaults) ----------------------------------------
  /** Governs the gamepad `back` intent as well: B and Escape share one lock. */
  readonly closeOnEscape?: boolean | undefined;
  readonly closeOnInteractOutside?: boolean | undefined;
  /** The click that closes the select must not activate what was under it. */
  readonly preventOutsideActivation?: boolean | undefined;
  /** `false` — the menu's justification, verbatim: inert + scroll lock is the dialog's contract. */
  readonly modal?: boolean | undefined;
  /** Defaults to the `sheet` presentation and is ignored in `popup`. */
  readonly preventScroll?: boolean | undefined;
  readonly onDismiss?: ((details: SelectDismissDetails) => void) | undefined;
  /**
   * The layer this select opened from — required once either end is portalled,
   * or a click inside the portalled listbox reads as outside the surface that
   * holds the trigger. Adapters default it from their layer context.
   */
  readonly parentId?: string | undefined;

  // --- focus -----------------------------------------------------------------
  /** On by default. Turned off, focus is left wherever the dismissal put it and `finalFocus` is never consulted. */
  readonly restoreFocus?: boolean | undefined;
  /** Outranks the element that had focus when the select opened; ignored entirely while `restoreFocus` is off. */
  readonly finalFocus?: (() => HTMLElement | null) | undefined;

  // --- form ------------------------------------------------------------------
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  readonly required?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly disabled?: boolean | undefined;

  // --- misc ------------------------------------------------------------------
  /** The selection blink. Popup only; off in `sheet` and under reduced motion. */
  readonly selectionFlash?: boolean | undefined;
  /**
   * The accessible name of both halves when nothing else names them: the
   * listbox stops borrowing the trigger's name, and the trigger — a
   * `role="combobox"`, which takes no name from its contents — gets one at all.
   * Inside a `field`, prefer the field's label; `labelledBy` outranks this.
   */
  readonly label?: string | undefined;
  /** `aria-describedby` for the trigger — what a field's helper text wires in. */
  readonly describedBy?: string | undefined;
  /** `aria-labelledby` for the trigger, for a label `label[for]` cannot reach. */
  readonly labelledBy?: string | undefined;
  /** Spared by both the outside-interaction test and the modal inert treatment — what must stay live under an open listbox. */
  readonly persistentElements?: (() => readonly HTMLElement[]) | undefined;
  /** The intent bus engage mode pushes its scope onto. `null` by default, so the pad is off until a host is supplied. */
  readonly intents?: IntentScopeHost | null | undefined;
}

export interface ResolvedSelectMachineProps extends SelectMachineProps {
  readonly defaultValue: string | null;
  readonly defaultOpen: boolean;
  readonly presentation: SelectPresentationProp;
  readonly placement: Placement;
  readonly gap: number;
  readonly offset: number;
  readonly flip: boolean;
  readonly shift: boolean;
  readonly padding: number;
  readonly matchWidth: boolean;
  readonly strategy: "absolute" | "fixed";
  readonly loopFocus: boolean;
  readonly typeahead: boolean;
  readonly closeOnSelect: boolean;
  readonly closeOnEscape: boolean;
  readonly closeOnInteractOutside: boolean;
  readonly preventOutsideActivation: boolean;
  readonly modal: boolean;
  readonly restoreFocus: boolean;
  readonly required: boolean;
  readonly invalid: boolean;
  readonly disabled: boolean;
  readonly selectionFlash: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface SelectSchema extends MachineSchema {
  state: "open" | "closed";
  props: ResolvedSelectMachineProps;
  context: {
    /** The single source of truth; the state is a projection of it. */
    open: boolean;
    /** The app's value. The machine never invents one — no native-style "first item" fallback. */
    value: string | null;
    /**
     * The label captured for `value`, and the trigger's text while the surface
     * is closed. Back-filled from the DOM by `syncCollection`; when the item of
     * `value` disappears (a filter, a re-render) the **last capture survives** —
     * the value belongs to the app, and the machine will not mutate it d'office.
     */
    valueLabel: string | null;
    highlightedValue: string | null;
    density: Density;
    /**
     * The direction the portalled surface is drawn in, resolved from the anchor
     * when it opens. `null` until then — and on the server — which is what keeps
     * the first client render agreeing with the markup it hydrates.
     */
    surfaceDir: Direction | null;
    /** Where the surface landed — the preferred placement may have flipped. */
    currentPlacement: Placement;
    /** Whether any row draws a glyph. The selection gutter has no twin: it is constant. */
    hasSymbolGutter: boolean;
    /** The item mid-blink; the close is deferred until it ends. */
    flashingValue: string | null;
    /** The modality the highlight arrived under, held until it moves again. */
    focusSource: InputModality | null;
  };
  computed: {
    presentation: SelectPresentation;
    hasValue: boolean;
  };
  refs: {
    finalFocusEl: HTMLElement | null;
    typeahead: TypeaheadState;
    /** The keystroke that *opened* the select, honoured once the items exist. */
    pendingTypeaheadKey: string | null;
    /** Where the keyboard asked the highlight to land before there was a surface. */
    pendingHighlight: RovingAction | null;
    /** Owned by `trackSelectionFlash`; cancelled the moment the surface leaves. */
    flashTimer: VoidFunction | null;
    /** Press-drag-release: the click that follows the opening press is not a toggle. */
    openedAt: number;
    /** The last close asked for was `ITEM.COMMIT` — the one a held modal Tab rides on. */
    closedByCommit: boolean;
    /** The photo `FORM.RESET` restores. */
    initialValue: string | null;
    /** Which value the current `valueLabel` was captured for — see `syncCollection`. */
    labelValue: string | null;
  };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "TRIGGER.POINTERDOWN" }
    | { type: "TRIGGER.KEYDOWN"; action: RovingAction }
    | { type: "ITEM.POINTERMOVE"; value: string }
    | { type: "ITEM.POINTERLEAVE"; value: string }
    | { type: "ITEM.CLICK"; value: string }
    | { type: "ITEM.ACTIVATE" }
    /**
     * Commit the highlight and close, without the blink. Tab and Alt+ArrowUp:
     * both hand the focus somewhere else in the same gesture, so the 150ms the
     * blink holds the surface open would be spent on a surface nobody is
     * looking at — and Tab's proxy would carry the focus out from under it.
     */
    | { type: "ITEM.COMMIT" }
    | { type: "HIGHLIGHT.MOVE"; action: RovingAction }
    /** PageUp/PageDown — a page is ten options, clamped at either end. */
    | { type: "HIGHLIGHT.PAGE"; direction: "next" | "prev" }
    /** `null` clears it — there is no second event for that. */
    | { type: "HIGHLIGHT.SET"; value: string | null }
    | { type: "TYPEAHEAD.KEY"; key: string }
    /** `api.setValue`/`clearValue` — never touches `open`. */
    | { type: "VALUE.SET"; value: string | null }
    | { type: "FLASH.END" }
    | { type: "CONTENT.DISMISS"; reason: DismissReason }
    | { type: "CANCEL.CLICK" }
    | { type: "POSITION.SYNC"; placement: Placement }
    | { type: "OPEN.SET"; open: boolean }
    | { type: "OPEN.SYNC" }
    | { type: "PRESENTATION.SYNC" }
    | { type: "ENVIRONMENT.SYNC"; density: Density }
    | { type: "COLLECTION.SYNC" }
    | { type: "FORM.RESET" };
  action:
    | "openSelect"
    | "closeSelect"
    | "setOpen"
    | "captureFinalFocus"
    | "clearTransient"
    | "highlightInitial"
    | "highlightItem"
    | "clearHighlight"
    | "moveHighlight"
    | "pageHighlight"
    | "focusHighlighted"
    | "typeaheadHighlight"
    | "deferTypeaheadKey"
    | "selectItem"
    | "commitHighlighted"
    | "activateHighlighted"
    | "flashSelection"
    | "clearFlash"
    | "invokeOnDismiss"
    | "setValue"
    | "resetToInitialValue"
    | "syncEnvironment"
    | "syncPlacement"
    | "syncCollection";
  guard:
    | "isEnabled"
    | "isOpen"
    | "isItemEnabled"
    | "hasHighlight"
    | "isLeavingHighlighted"
    | "shouldCloseOnSelect"
    | "shouldFlash"
    | "isTypeaheadEnabled"
    | "canDismiss"
    | "isWithinReopenGrace";
  effect:
    | "trackEnvironment"
    | "trackModality"
    | "trackSurfaceDir"
    | "trackCollection"
    | "trackFormReset"
    | "trackDismissable"
    | "lockPageScroll"
    | "trackAnchorPosition"
    | "focusContent"
    | "proxyTabs"
    | "hideOutside"
    | "captureIntents"
    | "trackSelectionFlash"
    | "trackScrollEdges";
}

// --- prop-getter inputs ------------------------------------------------------

export interface SelectItemProps {
  readonly value: string;
  readonly disabled?: boolean | undefined;
  /** Typeahead text and `data-label`; falls back to the `itemText` part. */
  readonly label?: string | undefined;
}

export interface SelectItemGroupProps {
  /** Ties the group to its label. Any stable string the consumer owns. */
  readonly id: string;
  /**
   * The group renders an `itemGroupLabel` part — wires `aria-labelledby`.
   * Declared, never assumed: written blind, the attribute is a dead IDREF *and*
   * no accessible name at once (same shape as `MenuItemGroupProps.label`).
   */
  readonly label?: boolean | undefined;
}

export interface SelectItemGroupLabelProps {
  readonly htmlFor: string;
}

export interface SelectItemIndicatorProps {
  readonly value: string;
}

export interface SelectApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  readonly value: string | null;
  /** Captured label of the value (see the schema's `valueLabel`); `null` until anything resolved. */
  readonly valueLabel: string | null;
  readonly hasValue: boolean;
  readonly highlightedValue: string | null;
  readonly presentation: SelectPresentation;
  /** Where the surface landed, which is not necessarily what was asked for. */
  readonly placement: Placement;
  readonly triggerId: string;
  readonly contentId: string;

  setOpen(open: boolean): void;
  setValue(value: string | null): void;
  /** Sugar for `setValue(null)`. */
  clearValue(): void;
  setHighlightedValue(value: string | null): void;

  getTriggerProps(): T["button"];
  getValueTextProps(): T["element"];
  getIndicatorProps(): T["element"];
  getHiddenSelectProps(): T["select"];
  getBackdropProps(): T["element"];
  getPositionerProps(): T["element"];
  getContentProps(): T["element"];
  getItemGroupProps(props: SelectItemGroupProps): T["element"];
  getItemGroupLabelProps(props: SelectItemGroupLabelProps): T["element"];
  getItemProps(props: SelectItemProps): T["element"];
  getItemTextProps(): T["element"];
  getItemSymbolProps(): T["element"];
  getItemIndicatorProps(props: SelectItemIndicatorProps): T["element"];
  getSeparatorProps(): T["element"];
  getCancelTriggerProps(): T["button"];
}

/**
 * `<Select options={…}/>` — the other end of the fork from `<Button>`: fifteen
 * nodes, two loops, and a root that renders no element at all. `SelectRoot`
 * publishes a context and stops; `Select` renders the whole tree — the trigger,
 * the form mirror, the portal, the surface and its rows — which is the difference
 * between the two names, and the first line of this file for that reason.
 *
 * Everything below is a placement. There is no state here, no memo over the
 * collection, no prop getter rewritten: the collection is still the live DOM the
 * machine reads, and mapping an array into `<SelectItem>` elements before the
 * render holds nothing (`menu.tsx`, the invariant, unchanged).
 *
 * Two translations the type system cannot do on its own, and both are a11y
 * defects if they are skipped:
 *
 *  - A group's `label` is **the text** here and **a boolean flag** on the part
 *    (`SelectItemGroupProps.label`). Passing the string through would be truthy,
 *    so `aria-labelledby` would be written and point at a label part nobody
 *    rendered. `id` is required on a group so the two ends meet, and so the
 *    markup-parity fixture can pin the key the part would otherwise mint.
 *  - An option's `label` is its typeahead text, its `data-label` *and* the text
 *    the row shows. It is **required** here where the part leaves it optional,
 *    because this is the only place all three come from: the part's fallback
 *    reads `SelectItemText`, which the composed layer fills from this very field.
 *    `renderOption` receives the default subtree rather than a blank slate so
 *    that *decorating* is the cheapest path; replacing it stays the consumer's to
 *    do, and costs them the part that names the row.
 */

import type { SelectItemProps as CoreSelectItemProps } from "@standarui/core/select";
import type { ReactNode } from "react";
import type {
  ComposedDecoration,
  ComposedGroup,
  ComposedSeparator,
  ComposedTrigger,
} from "../../composed";
import type { PartProps } from "../../create-part";
import type { PortalProps } from "../../portal";
import {
  SelectBackdrop,
  SelectCancelTrigger,
  SelectContent,
  SelectHiddenSelect,
  SelectIndicator,
  SelectItem,
  SelectItemGroup,
  SelectItemGroupLabel,
  type SelectItemGroupProps,
  SelectItemIndicator,
  SelectItemSymbol,
  SelectItemText,
  SelectPortal,
  type SelectPortalProps,
  SelectPositioner,
  SelectRoot,
  SelectSeparator,
  SelectTrigger,
  SelectValueText,
  type SelectValueTextProps,
  type UseSelectProps,
} from "./select";

/**
 * An option is the part's own props — an intersection, never a `Pick`, so a field
 * added to `SelectItemProps` shows up here without anyone thinking about it —
 * plus the two fields no machine owns, and `label` narrowed from optional to
 * required (see the header: the composed row has nothing else to name itself
 * with, and a nameless `role="option"` is not a shape to leave compilable).
 */
export type SelectOption<V extends string = string, Meta = never> = Omit<
  CoreSelectItemProps,
  "value" | "label"
> &
  ComposedDecoration<Meta> & {
    readonly value: V;
    readonly label: string;
  };

/** Narrowed structurally: `"separator" in entry`, then `"options" in entry`. */
export type SelectEntry<V extends string = string, Meta = never> =
  | SelectOption<V, Meta>
  | ComposedGroup<SelectOption<V, Meta>>
  | ComposedSeparator;

/**
 * The escape hatch, applied **last** on every part: the composed layer's own
 * props default what it places, and the consumer's entry wins over them.
 *
 * Sixteen keys for fifteen parts: the anatomy's fifteen (`select.anatomy.ts`),
 * plus `portal` — which is no part at all but the React container the parts form
 * wraps them in (`SelectPortalProps`), and the one key here that reaches an
 * element the machine never names.
 */
export interface SelectParts {
  readonly trigger?: PartProps<"button"> | undefined;
  readonly valueText?: SelectValueTextProps | undefined;
  readonly indicator?: PartProps<"span"> | undefined;
  readonly portal?: SelectPortalProps | undefined;
  readonly backdrop?: PartProps<"div"> | undefined;
  readonly positioner?: PartProps<"div"> | undefined;
  readonly content?: PartProps<"div"> | undefined;
  /** Applied to EVERY group — `id` and `label` are the entry's, one per group. */
  readonly itemGroup?: Omit<SelectItemGroupProps, "id" | "label"> | undefined;
  readonly itemGroupLabel?: PartProps<"div"> | undefined;
  /**
   * Applied to EVERY item, hence no `id` **and no IDREF**: one `id` repeated down
   * a listbox is a broken IDREF per row, and one `aria-labelledby` repeated gives
   * every option the same name — which `danglingIdRefs` cannot see, because the
   * id it points at does resolve. `ref` goes for the same reason: a single ref
   * held by N rows ends up holding the last one.
   */
  readonly item?:
    | Omit<
        PartProps<"div">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly itemText?: PartProps<"span"> | undefined;
  readonly itemIndicator?: PartProps<"span"> | undefined;
  readonly itemSymbol?: PartProps<"span"> | undefined;
  readonly separator?: PartProps<"div"> | undefined;
  readonly cancelTrigger?: PartProps<"button"> | undefined;
  readonly hiddenSelect?: PartProps<"select"> | undefined;
}

export interface SelectComposedProps<V extends string = string, Meta = never>
  extends UseSelectProps {
  readonly options: readonly SelectEntry<V, Meta>[];
  /** Shown by the trigger while nothing is selected. */
  readonly placeholder?: string | undefined;
  /**
   * Handed to `SelectTrigger` as `render` — never as its children. The trigger
   * *is* a `<button>`, and a button inside a button is `nested-interactive`.
   *
   * The substitution brings the element **and its behaviour** with it —
   * `ButtonRoot` infers `nativeButton` from what it actually renders — and the
   * look follows the element too: `_select.scss:41` and `:84` are the library's
   * only `select:trigger` rules and both stand behind `:not([data-part*=" "])`,
   * so the pop-up form withholds itself the moment a second identity lands on the
   * element. That is the composition point the sheet declares out loud
   * (`_select.scss:29-32`, "the button's sheet owns the form"), not an accident of
   * source order. The chevron cell is not gated and stays: `select:indicator` is
   * a child, not the composed element.
   */
  readonly trigger?: ComposedTrigger | undefined;
  /**
   * The sheet's Cancel card. The part withholds itself in `popup` on its own, and
   * `null` withholds it here — an empty `<button>` would have no accessible name,
   * and `getCancelTriggerProps` writes none.
   */
  readonly cancelLabel?: ReactNode;
  readonly container?: PortalProps["container"] | undefined;
  /** `true` by default, as on `SelectRoot` — the collection is in the markup while closed. */
  readonly keepMounted?: boolean | undefined;
  /**
   * Replaces the CHILDREN of an item, never the item. `defaults` is the row the
   * layer would have rendered — indicator, symbol, text — and it is handed over
   * so that **decorating** is the cheapest thing to do, not because replacing is
   * impossible. Rendering something else instead of `defaults` is the consumer's
   * to do and costs them three things: the part that names the option
   * (`SelectItemText`), the selection checkmark, and the leading column those two
   * share.
   *
   * Decorate as a **sibling** of `defaults`, never by wrapping it in an element:
   * an item's children are its grid cells (`_select.scss:382`,
   * `grid-template-columns` on `select:item`), so a wrapper collapses all three
   * into one and a node with no `grid-column` of its own lands in the leading
   * track.
   */
  readonly renderOption?:
    | ((option: SelectOption<V, Meta>, defaults: ReactNode) => ReactNode)
    | undefined;
  readonly parts?: SelectParts | undefined;
}

/**
 * One row. `icon` and `meta` are lifted out because the rest of the entry is
 * spread straight onto the part: `icon` belongs to a part of its own and `meta`
 * belongs to the consumer, and neither is an attribute of a `<div>`.
 */
function renderItem<V extends string, Meta>(
  option: SelectOption<V, Meta>,
  parts: SelectParts | undefined,
  render: ((option: SelectOption<V, Meta>, defaults: ReactNode) => ReactNode) | undefined,
): ReactNode {
  const { icon, meta, ...item } = option;
  const defaults = (
    <>
      <SelectItemIndicator {...parts?.itemIndicator} />
      {icon === undefined ? null : (
        <SelectItemSymbol {...parts?.itemSymbol}>{icon}</SelectItemSymbol>
      )}
      <SelectItemText {...parts?.itemText}>{option.label}</SelectItemText>
    </>
  );

  return (
    <SelectItem key={option.value} {...item} {...parts?.item}>
      {render === undefined ? defaults : render(option, defaults)}
    </SelectItem>
  );
}

export function Select<V extends string = string, Meta = never>(
  props: SelectComposedProps<V, Meta>,
): ReactNode {
  const { options, placeholder, trigger, cancelLabel, container, renderOption, parts, ...root } =
    props;

  return (
    <SelectRoot {...root}>
      <SelectTrigger render={trigger} {...parts?.trigger}>
        <SelectValueText placeholder={placeholder} {...parts?.valueText} />
        <SelectIndicator {...parts?.indicator} />
      </SelectTrigger>
      <SelectHiddenSelect {...parts?.hiddenSelect} />
      <SelectPortal container={container} {...parts?.portal}>
        <SelectBackdrop {...parts?.backdrop} />
        <SelectPositioner {...parts?.positioner}>
          <SelectContent {...parts?.content}>
            {options.map((entry, index) => {
              // A separator is not focusable, holds no state and has no subtree to
              // unmount, where an index on a row would move the focus mid-interaction —
              // the collection being the live DOM the machine reads.
              if ("separator" in entry) {
                // biome-ignore lint/suspicious/noArrayIndexKey: safe on a separator, and on nothing else in this list — see above.
                return <SelectSeparator key={`sep:${index}`} {...parts?.separator} />;
              }
              if ("options" in entry) {
                return (
                  <SelectItemGroup key={entry.id} id={entry.id} label {...parts?.itemGroup}>
                    <SelectItemGroupLabel {...parts?.itemGroupLabel}>
                      {entry.label}
                    </SelectItemGroupLabel>
                    {entry.options.map((option) => renderItem(option, parts, renderOption))}
                  </SelectItemGroup>
                );
              }
              return renderItem(entry, parts, renderOption);
            })}
          </SelectContent>
          {cancelLabel == null ? null : (
            <SelectCancelTrigger {...parts?.cancelTrigger}>{cancelLabel}</SelectCancelTrigger>
          )}
        </SelectPositioner>
      </SelectPortal>
    </SelectRoot>
  );
}

/**
 * The select in React: the menu's shape — a root that renders no element, a
 * portalled surface, two presences — with two inversions of its own.
 *
 * **The content is mounted by default** (`keepMounted` defaults to `true`, the
 * exact opposite of menu and popover), because the collection is the DOM and the
 * select has a value: the closed trigger shows the selected label, the closed
 * typeahead finds the items, and the form mirror knows the selection — three
 * reads that need the items to exist while the surface is visually gone. The
 * closed surface is hidden by the stylesheet (`data-state="closed"` →
 * `visibility: hidden`), which also takes it out of the accessibility tree and
 * the tab order without unmounting it.
 *
 * **The form is real.** `SelectHiddenSelect` renders a native `<select>` with a
 * single mirrored `<option>` — the submission only needs the selection, and a
 * full mirror of the collection would be paid on every render.
 */

import * as select from "@standarui/core/select";
import { type ReactNode, type Ref, useId, useMemo } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { useFieldContext } from "../../field-context";
import { LayerProvider, useParentLayerId } from "../../layer-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { Portal, type PortalProps } from "../../portal";
import { type PresenceApi, usePresence } from "../../presence";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type SelectApi = select.SelectApi<ReactPropTypes>;

export interface UseSelectProps extends select.SelectMachineProps, MachineRuntimeProps {}

interface SelectContextValue {
  readonly api: SelectApi;
  readonly keepMounted: boolean;
  readonly backdrop: PresenceApi;
  readonly content: PresenceApi;
}

const SelectContext = createPartContext<SelectContextValue>("Select");
const SelectItemContext = createPartContext<string>("Select");
const SelectGroupContext = createPartContext<string>("Select");

/**
 * The machine on its own, for a consumer who would rather write the markup than
 * compose the parts.
 */
export function useSelect(props: UseSelectProps): SelectApi {
  const host = useIntentScopeHost();
  const parentLayerId = useParentLayerId();

  const service = useMachine(select.machine, {
    ...props,
    // `??` would override an explicit `null`, which is how a consumer says
    // "this surface answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
    // A select opened from inside another surface carries that surface's layer
    // id, so a click in the portalled listbox never dismisses its host.
    parentId: props.parentId ?? parentLayerId,
  });
  return select.connect(service, normalizeProps);
}

export function useSelectContext(): SelectApi {
  return SelectContext.usePart("SelectContext").api;
}

export interface SelectRootProps extends UseSelectProps {
  /**
   * `true` by default — the inverse of menu and popover, and the price of "the
   * collection is the DOM" on a component with a value (see the module header).
   * Opting out is for a consumer who feeds `value` and the `SelectValueText`
   * children from their own model: without them a closed trigger shows the
   * placeholder over a value.
   */
  readonly keepMounted?: boolean | undefined;
  readonly children?: ReactNode;
}

export function SelectRoot(props: SelectRootProps): ReactNode {
  const { children, keepMounted, ...machineProps } = props;
  const field = useFieldContext();
  const api = useSelect({
    ...machineProps,
    // The field's flags reach the machine as props rather than being merged
    // over its output — `??`, so a control that answers for itself wins.
    disabled: machineProps.disabled ?? field?.disabled,
    invalid: machineProps.invalid ?? field?.invalid,
    required: machineProps.required ?? field?.required,
    describedBy: machineProps.describedBy ?? field?.controlProps["aria-describedby"],
    // The trigger is the labelable control here (`<button>`), so it wears the
    // field's control id and `label[for]` resolves natively.
    ids: { trigger: field?.controlProps.id, ...machineProps.ids },
  });
  const { motion } = useEnvironment();
  // See the note in `dialog.tsx`: `reduced` keeps the fade, only `none` removes it.
  const immediate = motion === "none";

  // Two presences: the scrim and the surface run different exits, and one
  // presence can only measure the animations of the node it holds.
  const backdrop = usePresence({ present: api.open, immediate });
  const content = usePresence({ present: api.open, immediate });

  const value: SelectContextValue = {
    api,
    keepMounted: keepMounted !== false,
    backdrop,
    content,
  };

  return (
    <LayerProvider layerId={api.contentId}>
      <SelectContext.Provider value={value}>{children}</SelectContext.Provider>
    </LayerProvider>
  );
}

/**
 * Read straight off the machine in the open direction, never off the presence:
 * the interpreter installs the open state's effects in the layout effect of the
 * very commit that opened it, and every one of them looks the surface up by id.
 */
function isMounted(context: SelectContextValue, presence: PresenceApi): boolean {
  return context.keepMounted || context.api.open || presence.present;
}

function usePresenceRef(
  presence: PresenceApi,
  consumer: Ref<HTMLElement> | undefined,
): Ref<HTMLElement> {
  return useMemo(() => composeRefs(presence.ref, consumer), [presence.ref, consumer]);
}

export const SelectTrigger: (props: PartProps<"button">) => ReactNode = createPart(SelectContext, {
  name: "SelectTrigger",
  element: "button",
  props: (context) => context.api.getTriggerProps(),
});

export interface SelectValueTextProps extends PartProps<"span"> {
  /** Shown while nothing is selected. `children` wins, then the captured label. */
  readonly placeholder?: string | undefined;
}

export function SelectValueText(props: SelectValueTextProps): ReactNode {
  const { render, asChild, children, placeholder, ...elementProps } = props;
  const context = SelectContext.usePart("SelectValueText");
  const { api } = context;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getValueTextProps(),
    elementProps,
    children: children ?? api.valueLabel ?? placeholder,
  });
}

/** The double chevron. Decoration — an inline SVG, never a text glyph. */
export const SelectIndicator: (props: PartProps<"span">) => ReactNode = createPart(SelectContext, {
  name: "SelectIndicator",
  element: "span",
  props: (context) => context.api.getIndicatorProps(),
});

/**
 * The form mirror, a sibling of the trigger (a `<select>` inside a `<button>`
 * is invalid HTML). One `<option>`: the submission only needs the selection.
 * With no value the mirrored option is empty and selected, which is exactly
 * what makes `required` fail `checkValidity()` — the native validation, kept.
 */
export function SelectHiddenSelect(props: PartProps<"select">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = SelectContext.usePart("SelectHiddenSelect");
  const { api } = context;

  return useRender({
    render,
    asChild,
    element: "select",
    props: api.getHiddenSelectProps(),
    elementProps,
    // One `<option>` in both directions: with no value `api.value` is `null` by
    // construction (`hasValue` *is* `value !== null`), so the empty selected
    // option falls out of the same element rather than needing a second one.
    children: (
      <option value={api.value ?? ""}>{api.hasValue ? (api.valueLabel ?? api.value) : null}</option>
    ),
  });
}

export interface SelectPortalProps extends Omit<PortalProps, "children"> {
  readonly children?: ReactNode;
}

export function SelectPortal(props: SelectPortalProps): ReactNode {
  const { children, ...portalProps } = props;
  const context = SelectContext.usePart("SelectPortal");
  const present = isMounted(context, context.backdrop) || isMounted(context, context.content);

  if (!present) return null;
  return <Portal {...portalProps}>{children}</Portal>;
}

/**
 * The scrim, and the sheet's alone: an anchored popup that dimmed the page
 * would swallow the very click that is meant to dismiss it. Rendered then
 * discarded rather than returned early — `useRender` is a hook, and a density
 * flip must not change how many of them this component runs.
 */
export function SelectBackdrop(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const context = SelectContext.usePart("SelectBackdrop");
  const composed = usePresenceRef(context.backdrop, ref);

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getBackdropProps(),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  return context.api.presentation === "sheet" && isMounted(context, context.backdrop)
    ? element
    : null;
}

export function SelectPositioner(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = SelectContext.usePart("SelectPositioner");

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getPositionerProps(),
    elementProps,
    children,
  });

  return isMounted(context, context.content) ? element : null;
}

/**
 * The scroll affordance, two nodes the adapter writes rather than parts —
 * nothing composes into them and nothing renders inside them (see the menu,
 * whose arrangement this is). Outermost on both sides, so the first row slides
 * under the top band and the last under the bottom one.
 */
const SCROLL_EDGE_UP = <div data-scroll-edge="up" aria-hidden="true" />;
const SCROLL_EDGE_DOWN = <div data-scroll-edge="down" aria-hidden="true" />;

export function SelectContent(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const context = SelectContext.usePart("SelectContent");
  const composed = usePresenceRef(context.content, ref);

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getContentProps(),
    elementProps: { ...elementProps, ref: composed },
    children: (
      <>
        {SCROLL_EDGE_UP}
        {children}
        {SCROLL_EDGE_DOWN}
      </>
    ),
  });

  return isMounted(context, context.content) ? element : null;
}

export interface SelectItemGroupProps extends PartProps<"div", select.SelectItemGroupProps> {
  /** Any stable key of the consumer's; a `useId()` when they have none. */
  readonly id?: string | undefined;
  /**
   * **A flag, not the text.** Say `label` when the group renders a
   * `SelectItemGroupLabel`, and `aria-labelledby` is wired to it. Written blind
   * the attribute points at an element nobody rendered (the menu's lesson).
   */
  readonly label?: boolean | undefined;
}

export function SelectItemGroup(props: SelectItemGroupProps): ReactNode {
  const [group, rest] = splitProps(props, ["id", "label"]);
  const { render, asChild, children, ...elementProps } = rest;
  const context = SelectContext.usePart("SelectItemGroup");
  const fallback = useId();
  const key = group.id ?? fallback;

  return (
    <SelectGroupContext.Provider value={key}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: context.api.getItemGroupProps({ id: key, label: group.label }),
        elementProps,
        children,
      })}
    </SelectGroupContext.Provider>
  );
}

export function SelectItemGroupLabel(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = SelectContext.usePart("SelectItemGroupLabel");
  const htmlFor = SelectGroupContext.usePart("SelectItemGroupLabel");

  return useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getItemGroupLabelProps({ htmlFor }),
    elementProps,
    children,
  });
}

export interface SelectItemProps
  extends select.SelectItemProps,
    PartProps<"div", select.SelectItemProps> {}

export function SelectItem(props: SelectItemProps): ReactNode {
  const [item, rest] = splitProps(props, ["value", "disabled", "label"]);
  const { render, asChild, children, ...elementProps } = rest;
  const context = SelectContext.usePart("SelectItem");

  return (
    <SelectItemContext.Provider value={item.value}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: context.api.getItemProps(item),
        elementProps,
        children,
      })}
    </SelectItemContext.Provider>
  );
}

/** The option's accessible name, and the typeahead's fallback text. */
export const SelectItemText: (props: PartProps<"span">) => ReactNode = createPart(SelectContext, {
  name: "SelectItemText",
  element: "span",
  props: (context) => context.api.getItemTextProps(),
});

/**
 * The reserved symbol column, sharing one leading track with the checkmark.
 * Give it an inline SVG, never a text glyph: text stands on its font's baseline
 * inside the centred line box, so its ink paints below the box's centre.
 */
export const SelectItemSymbol: (props: PartProps<"span">) => ReactNode = createPart(SelectContext, {
  name: "SelectItemSymbol",
  element: "span",
  props: (context) => context.api.getItemSymbolProps(),
});

/**
 * The checkmark. The state is `aria-selected` on the item, never this glyph —
 * and like the symbol it takes an inline SVG, not a `✓` character.
 */
export function SelectItemIndicator(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = SelectContext.usePart("SelectItemIndicator");
  const value = SelectItemContext.usePart("SelectItemIndicator");

  return useRender({
    render,
    asChild,
    element: "span",
    props: context.api.getItemIndicatorProps({ value }),
    elementProps,
    children,
  });
}

export const SelectSeparator: (props: PartProps<"div">) => ReactNode = createPart(SelectContext, {
  name: "SelectSeparator",
  element: "div",
  props: (context) => context.api.getSeparatorProps(),
});

/**
 * The sheet's Cancel card, and only the sheet's — a sibling of the listbox
 * inside the positioner, never a child of it (a bare button inside a
 * `role="listbox"` is an owned-children violation). The hook runs
 * unconditionally; only the element is withheld (the MenuBackdrop rule).
 */
export function SelectCancelTrigger(props: PartProps<"button">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = SelectContext.usePart("SelectCancelTrigger");

  const element = useRender({
    render,
    asChild,
    element: "button",
    props: context.api.getCancelTriggerProps(),
    elementProps,
    children,
  });

  return context.api.presentation === "sheet" ? element : null;
}
